const handlers = moves.map(([act, from, to, why]) => {
  const branch = (k) => `[require($.task${k} === $.${from}, '${why}'), set('task${k}', $.${to}), ${derive(k, to)}]`;
  return `      on('${act}', ($) => [
        ${live},
        when($.task === 0, ${branch(0)},
          [when($.task === 1, ${branch(1)},
            ${branch(2)})]),
      ], ['task']),`;
}).join('\n');
const actions = moves.map(([act]) => `      action('${act}', { task: t.int.check([0, 1, 2], 'strict') }),`).join('\n');
