import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const ok = { ok: true };

test('start, duplicate start, unknown run', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.equal((await h.taskStarted('a', 0)).ok, false);
  assert.equal(await h.run('a'), null);
  assert.deepEqual(await h.start('a'), ok);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.start('a')).ok, false);
});

test('bad task numbers and illegal moves are refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [3, -1, 1.5]) assert.equal((await h.taskStarted('r', t)).ok, false);
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  assert.equal((await h.taskRequeued('r', 0)).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('completion of all tasks', async () => {
  const h = await createHost();
  await h.start('r');
  assert.deepEqual(await h.taskStarted('r', 0), ok);
  assert.equal((await h.run('r'))!.status, 'running');
  for (const t of [1, 2]) await h.taskStarted('r', t);
  for (const t of [0, 1]) await h.taskCompleted('r', t);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 2);
  assert.deepEqual(await h.run('r'), { status: 'completed', task0: 'completed', task1: 'completed', task2: 'completed' });
  assert.equal((await h.cancel('r')).ok, false);
});

test('eviction keeps the run running, all evicted shows evicted', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) await h.taskStarted('r', t);
  await h.taskCompleted('r', 0);
  await h.taskCompleted('r', 1);
  await h.taskEvicted('r', 2);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.deepEqual(await h.taskRequeued('r', 2), ok);
  assert.equal((await h.run('r'))!.task2, 'queued');

  await h.start('s');
  for (const t of [0, 1, 2]) { await h.taskStarted('s', t); await h.taskEvicted('s', t); }
  assert.equal((await h.run('s'))!.status, 'evicted');
});

test('failure finalises the run', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 1);
  assert.deepEqual(await h.taskFailed('r', 1), ok);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'queued', task1: 'failed', task2: 'queued' });
  assert.equal((await h.taskStarted('r', 0)).ok, false);
  assert.equal((await h.cancel('r')).ok, false);
});

test('cancel', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskCompleted('r', 0);
  assert.deepEqual(await h.cancel('r'), ok);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
  assert.equal((await h.cancel('r')).ok, false);
});

