      invariant('failed-whenever-a-task-failed', ($) => implies($.task0 === $.failed || $.task1 === $.failed || $.task2 === $.failed, $.status === $.failed)),
      invariant('not-done-while-in-flight', ($) => implies(${anyInflight}, !isIn($.status, [$.completed, $.cancelled]))),
      invariant('unstarted-is-pristine', ($) => implies(!$.started, $.status === $.queued && $.task0 === $.queued && $.task1 === $.queued && $.task2 === $.queued)),
    ],
  }),
]);
`;
mkdirSync('src', { recursive: true });
writeFileSync('src/system.ts', src);

// Generates src/system.ts: the per-task branches are mechanical, so they are written out here.
import { mkdirSync, writeFileSync } from 'node:fs';
const T = [0, 1, 2];
const inflight = (e) => `isIn(${e}, [$.queued, $.running, $.evicted])`;
// The run's status after task k becomes `to`, the other two tasks unchanged.
function derive(k, to) {
  const [a, b] = T.filter((i) => i !== k).map((i) => `$.task${i}`);
  const v = `$.${to}`;
  const same = `${a} === ${v} && ${b} === ${v}`;
  const anyFailed = `${a} === $.failed || ${b} === $.failed`;
  if (to === 'failed') return `set('status', $.failed)`;
  if (['queued', 'running', 'evicted'].includes(to))
    return `when(${same}, [set('status', ${v})], [when(${anyFailed}, [set('status', $.failed)], [set('status', $.running)])])`;
  // completed or cancelled
  return `when(${same}, [set('status', ${v})], [when(${anyFailed}, [set('status', $.failed)], [when(${inflight(a)} || ${inflight(b)}, [set('status', $.running)], [set('status', $.cancelled)])])])`;
}
// [action, the statuses the task may move from, the status it moves to, the reason it is refused otherwise]
const moves = [
  ['TaskStarted', ['queued'], 'running', 'not-queued'],
  ['TaskCompleted', ['running'], 'completed', 'not-running'],
  ['TaskFailed', ['running'], 'failed', 'not-running'],
  ['TaskEvicted', ['running'], 'evicted', 'not-running'],
  ['TaskRequeued', ['evicted'], 'queued', 'not-evicted'],
  ['TaskRetried', ['failed'], 'queued', 'not-failed'],
  ['CancelTask', ['queued', 'running', 'evicted'], 'cancelled', 'task-final'],
];
// A failed run can still be retried; only completed and cancelled are the end of a run.
const live = `require($.started, 'not-started'), require(!isIn($.status, [$.completed, $.cancelled]), 'run-finished')`;
const handlers = moves.map(([act, from, to, why]) => {
  const may = (k) => (from.length === 1 ? `$.task${k} === $.${from[0]}` : `isIn($.task${k}, [${from.map((s) => `$.${s}`).join(', ')}])`);
  const branch = (k) => `[require(${may(k)}, '${why}'), set('task${k}', $.${to}), ${derive(k, to)}]`;
  // A paused run starts no queued task; every other command works as before.
  const pausedGuard = act === 'TaskStarted' ? `\n        require(!$.paused, 'run-paused'),` : '';
  return `      on('${act}', ($) => [
        ${live},${pausedGuard}
        when($.task === 0, ${branch(0)},
          [when($.task === 1, ${branch(1)},
            ${branch(2)})]),
      ], ['task']),`;
}).join('\n');
const actions = moves.map(([act]) => `      action('${act}', { task: t.int.check([0, 1, 2], 'strict') }),`).join('\n');
const cancelTask = (k) => `when(${inflight(`$.task${k}`)}, [set('task${k}', $.cancelled)])`;
const anyInflight = T.map((k) => inflight(`$.task${k}`)).join(' || ');
const src = `// Workflow run status: one Run machine per run id, created by start (generated by scripts/gen.mjs).
import { module, enumType, machine, field, t, action, on, require, set, when, terminal, invariant, implies, isIn } from '@cognitive-fab/poly/embed';

export default module('workflow', [
  enumType('Status', ['queued', 'running', 'evicted', 'completed', 'failed', 'cancelled']),
  machine('Run', {
    state: {
      status: field(t.named('Status'), ($) => $.queued),
      started: field(t.bool, () => false),
      task0: field(t.named('Status'), ($) => $.queued),
      task1: field(t.named('Status'), ($) => $.queued),
      task2: field(t.named('Status'), ($) => $.queued),
      paused: field(t.bool, () => false),
    },
    items: [
      terminal(($) => isIn($.status, [$.completed, $.cancelled])),
      action('Start', {}),
${actions}
      action('Cancel', {}),
      action('Pause', {}),
      action('Resume', {}),
      on('Pause', ($) => [${live}, require(!$.paused, 'already-paused'), set('paused', true)]),
      on('Resume', ($) => [${live}, require($.paused, 'not-paused'), set('paused', false)]),
      on('Start', ($) => [require(!$.started, 'run-exists'), set('started', true)]),
${handlers}
      on('Cancel', ($) => [
        ${live},
        require(${anyInflight}, 'nothing-in-flight'),
        ${T.map(cancelTask).join(',\n        ')},
        when($.task0 === $.failed || $.task1 === $.failed || $.task2 === $.failed, [set('status', $.failed)], [set('status', $.cancelled)]),
      ]),
      invariant('completed-only-when-all-completed', ($) => implies($.status === $.completed, $.task0 === $.completed && $.task1 === $.completed && $.task2 === $.completed)),
      invariant('failed-whenever-a-task-failed', ($) => implies($.task0 === $.failed || $.task1 === $.failed || $.task2 === $.failed, $.status === $.failed)),
      invariant('not-done-while-in-flight', ($) => implies(${anyInflight}, !isIn($.status, [$.completed, $.cancelled]))),
      invariant('unstarted-is-pristine', ($) => implies(!$.started, $.status === $.queued && $.task0 === $.queued && $.task1 === $.queued && $.task2 === $.queued)),
    ],
  }),
]);
`;
mkdirSync('src', { recursive: true });
writeFileSync('src/system.ts', src);

