  assert.deepEqual(await h.cancelTask('r', 2), ok);
  assert.deepEqual(await h.resume('r'), ok);
  assert.deepEqual(await h.taskStarted('r', 0), ok);
  await h.pause('r');
  assert.deepEqual(await h.taskEvicted('r', 0), ok);
  assert.deepEqual(await h.taskRequeued('r', 0), ok);
  assert.equal((await h.taskStarted('r', 0)).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'queued', task1: 'queued', task2: 'cancelled', paused: true });
  assert.deepEqual(await h.cancel('r'), ok);
  assert.equal((await h.resume('r')).ok, false);
  assert.equal((await h.run('r'))!.paused, true);
});
